/** chạy một lần: ước tính số lượt truy cập từ ngày bắt đầu sử dụng = số (người dùng × ngày) có hoạt động trong dữ liệu */
function visitBase_() {
  const p = PropertiesService.getScriptProperties();
  if (p.getProperty('VISIT_BASE_DONE')) return;
  const tz = 'Asia/Ho_Chi_Minh', day = t => { const x = new Date(t); return isNaN(x) ? '' : Utilities.formatDate(x, tz, 'yyyyMMdd'); };
  const seen = {}, add = (who, t) => { const d = day(t); if (who && d) seen[who + '|' + d] = d; };
  rows_('HocSinh').forEach(h => add(h.MaHS, h.NgayTao));
  rows_('GiaoVien').forEach(g => add(g.MaGV, g.NgayTao));
  rows_('KetQua').forEach(r => add(r.MaHS, r.ThoiDiem));
  try { rows_('NopVe').forEach(r => add(r.MaHS, r.ThoiDiem)); } catch (e) {}
  ['BaiGiao', 'BaiVe', 'MaTran', 'DeThi', 'TroChoi'].forEach(n => { try { rows_(n).forEach(r => add(r.MaGV, r.NgayTao)); } catch (e) {} });
  const days = Object.keys(seen).map(k => seen[k]), today = Utilities.formatDate(new Date(), tz, 'yyyyMMdd');
  const base = days.length, baseToday = days.filter(d => d === today).length, since = days.sort()[0] || today;
  const curDay = p.getProperty('VISIT_DAY');
  p.setProperties({ VISIT_TOTAL: String(Number(p.getProperty('VISIT_TOTAL') || 0) + base), VISIT_DAY: today,
    VISIT_TODAY: String((curDay === today ? Number(p.getProperty('VISIT_TODAY') || 0) : 0) + baseToday),
    VISIT_SINCE: since.slice(6, 8) + '/' + since.slice(4, 6) + '/' + since.slice(0, 4), VISIT_BASE_DONE: '1' });
}
